"""Deterministic Risk Management & Safety Firewall Module."""

import logging
from datetime import date
from pathlib import Path
from typing import Dict, List, Optional, Tuple
from pydantic import BaseModel, Field

from config.settings import settings
from data.earnings import EarningsFilter

logger = logging.getLogger(__name__)


class OrderProposal(BaseModel):
    """Proposal generated by strategy before risk validation."""
    ticker: str
    target_usd: float
    current_price: float
    reason: str = "Strategy Signal"


class ApprovedOrder(BaseModel):
    """Order vetted and approved by the risk engine."""
    ticker: str
    quantity: int
    estimated_price: float
    allocated_usd: float
    side: str = "BUY"  # BUY or SELL


class RiskManager:
    """Hard-coded deterministic safety rules protecting capital.

    Rules Enforced:
    1. Emergency Kill Switch check (halts trading if flagged).
    2. Earnings Blackout rejection (no holding into earnings tonight or tomorrow morning).
    3. Position size ceiling (e.g. max $1,000 per ticker).
    4. Portfolio total exposure ceiling (e.g. max $5,000 total across all positions).
    5. Daily loss circuit breaker (stops buys if daily loss exceeds threshold).
    6. Whole-share sizing based on available cash.
    """

    def __init__(
        self,
        max_position_size_usd: Optional[float] = None,
        max_portfolio_exposure_usd: Optional[float] = None,
        max_daily_loss_usd: Optional[float] = None,
        kill_switch_path: Optional[Path] = None,
    ):
        self.max_position_size_usd = (
            max_position_size_usd
            if max_position_size_usd is not None
            else settings.MAX_POSITION_SIZE_USD
        )
        self.max_portfolio_exposure_usd = (
            max_portfolio_exposure_usd
            if max_portfolio_exposure_usd is not None
            else settings.MAX_PORTFOLIO_EXPOSURE_USD
        )
        self.max_daily_loss_usd = (
            max_daily_loss_usd
            if max_daily_loss_usd is not None
            else settings.MAX_DAILY_LOSS_USD
        )
        self.kill_switch_file = (
            kill_switch_path or settings.DATA_DIR / ".kill_switch"
        )
        self.earnings_filter = EarningsFilter()

    def is_kill_switch_active(self) -> bool:
        """Check if manual emergency kill switch has been activated."""
        return self.kill_switch_file.exists()

    def activate_kill_switch(self, reason: str = "Manual Trigger"):
        """Activate the kill switch by creating the lock file."""
        self.kill_switch_file.parent.mkdir(parents=True, exist_ok=True)
        self.kill_switch_file.write_text(f"ACTIVATED: {reason}\n")
        logger.warning(f"EMERGENCY KILL SWITCH ACTIVATED: {reason}")

    def deactivate_kill_switch(self):
        """Deactivate kill switch by removing lock file."""
        if self.kill_switch_file.exists():
            self.kill_switch_file.unlink()
            logger.info("Emergency kill switch deactivated.")

    def evaluate_proposals(
        self,
        proposals: List[OrderProposal],
        available_cash: float,
        current_portfolio_exposure: float,
        daily_realized_loss: float = 0.0,
        trade_date: Optional[date] = None,
    ) -> Tuple[List[ApprovedOrder], List[str]]:
        """Validate a list of proposed BUY orders against hard deterministic safety rules.

        Returns:
            Tuple of (ApprovedOrders, RejectionReasons)
        """
        approved_orders: List[ApprovedOrder] = []
        rejections: List[str] = []
        ref_date = trade_date or date.today()

        # 1. Kill Switch Check
        if self.is_kill_switch_active():
            rejection_msg = "KILL SWITCH IS ACTIVE. All trading orders rejected."
            logger.error(rejection_msg)
            return [], [rejection_msg]

        # 2. Daily Loss Circuit Breaker
        if daily_realized_loss >= self.max_daily_loss_usd:
            msg = (
                f"DAILY LOSS CIRCUIT BREAKER TRIPPED: Realized loss ${daily_realized_loss:.2f} "
                f"exceeds ceiling ${self.max_daily_loss_usd:.2f}."
            )
            logger.warning(msg)
            return [], [msg]

        running_cash = available_cash
        running_exposure = current_portfolio_exposure

        for prop in proposals:
            ticker = prop.ticker.upper().strip()

            # Rule A: Check Earnings Blackout
            if self.earnings_filter.has_earnings_blackout(ticker, target_date=ref_date):
                msg = f"{ticker}: REJECTED due to upcoming earnings announcement blackout."
                logger.info(msg)
                rejections.append(msg)
                continue

            # Rule B: Validate Price
            if prop.current_price <= 0:
                msg = f"{ticker}: REJECTED due to invalid price ${prop.current_price:.2f}."
                logger.warning(msg)
                rejections.append(msg)
                continue

            # Rule C: Apply Max Position Size Cap
            allocated_cap = min(prop.target_usd, self.max_position_size_usd)

            # Rule D: Check Total Portfolio Exposure Cap
            available_exposure_room = self.max_portfolio_exposure_usd - running_exposure
            if available_exposure_room <= 0:
                msg = (
                    f"{ticker}: REJECTED - Portfolio exposure ceiling (${self.max_portfolio_exposure_usd:,.2f}) "
                    f"reached (current: ${running_exposure:,.2f})."
                )
                logger.info(msg)
                rejections.append(msg)
                continue

            allocated_cap = min(allocated_cap, available_exposure_room)

            # Rule E: Cash Solvency Check
            if running_cash < prop.current_price:
                msg = f"{ticker}: REJECTED - Insufficient cash (${running_cash:,.2f}) for 1 share (${prop.current_price:,.2f})."
                logger.info(msg)
                rejections.append(msg)
                continue

            allocated_cap = min(allocated_cap, running_cash)

            # Whole Share Sizing
            shares = int(allocated_cap // prop.current_price)
            if shares <= 0:
                msg = f"{ticker}: REJECTED - Sized to 0 shares after constraints."
                logger.info(msg)
                rejections.append(msg)
                continue

            order_cost = shares * prop.current_price
            running_cash -= order_cost
            running_exposure += order_cost

            approved = ApprovedOrder(
                ticker=ticker,
                quantity=shares,
                estimated_price=prop.current_price,
                allocated_usd=order_cost,
                side="BUY",
            )
            approved_orders.append(approved)
            logger.info(
                f"{ticker}: APPROVED - {shares} shares @ ${prop.current_price:.2f} = ${order_cost:,.2f}"
            )

        return approved_orders, rejections
